import { useState, useRef, useCallback, useEffect } from "react";
import "./carousel.css";

// Demo content — swap `slides` for your own data (title + subtitle + image url).
const DEFAULT_SLIDES = [
  { id: 1, title: "Kyoto, Japan", subtitle: "Maples along the Philosopher's Path", image: "https://picsum.photos/seed/kyoto-path/900/1100" },
  { id: 2, title: "Faroe Islands", subtitle: "Grass-roofed villages above the fjord", image: "https://picsum.photos/seed/faroe-islands/900/1100" },
  { id: 3, title: "Marrakech", subtitle: "Spice stalls in the Jemaa el-Fnaa souk", image: "https://picsum.photos/seed/marrakech-souk/900/1100" },
  { id: 4, title: "Patagonia", subtitle: "Granite towers over Lago Torre", image: "https://picsum.photos/seed/patagonia-towers/900/1100" },
  { id: 5, title: "Lofoten", subtitle: "Fishing huts under the midnight sun", image: "https://picsum.photos/seed/lofoten-huts/900/1100" },
];

/* @controls:start */
const DEFAULTS = {
  accent: "#ffffff",
  dotColor: "#d4d4d8",
  cardWidth: 280,
  cardHeight: 400,
  radius: 16,
  spacing: 62,
  sideScale: 0.74,
  speed: 520,
  showArrows: true,
  showDots: true,
  showCaption: true,
};
/* @controls:end */

// Shortest signed distance from `index` to `i` on a ring of size `count`.
function ringOffset(i, index, count) {
  let d = i - index;
  if (d > count / 2) d -= count;
  if (d < -count / 2) d += count;
  return d;
}

function Chevron({ direction }) {
  const points = direction === "left" ? "15 18 9 12 15 6" : "9 18 15 12 9 6";
  return (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <polyline points={points} />
    </svg>
  );
}

export default function Carousel({
  slides = DEFAULT_SLIDES,
  accent = DEFAULTS.accent,
  dotColor = DEFAULTS.dotColor,
  cardWidth = DEFAULTS.cardWidth,
  cardHeight = DEFAULTS.cardHeight,
  radius = DEFAULTS.radius,
  spacing = DEFAULTS.spacing,
  sideScale = DEFAULTS.sideScale,
  speed = DEFAULTS.speed,
  showArrows = DEFAULTS.showArrows,
  showDots = DEFAULTS.showDots,
  showCaption = DEFAULTS.showCaption,
}) {
  const [index, setIndex] = useState(0);
  const containerRef = useRef(null);
  const count = slides.length;

  const goTo = useCallback(
    (i) => setIndex(((i % count) + count) % count),
    [count]
  );
  const next = useCallback(() => goTo(index + 1), [goTo, index]);
  const prev = useCallback(() => goTo(index - 1), [goTo, index]);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const onKey = (e) => {
      if (e.key === "ArrowLeft") prev();
      if (e.key === "ArrowRight") next();
    };
    el.addEventListener("keydown", onKey);
    return () => el.removeEventListener("keydown", onKey);
  }, [next, prev]);

  // Only render cards close enough to the center to matter.
  const visible = slides
    .map((slide, i) => ({ slide, i, offset: ringOffset(i, index, count) }))
    .filter((s) => Math.abs(s.offset) <= 2);

  const styleFor = (offset) => {
    const abs = Math.abs(offset);
    // Each step further out keeps shrinking by the same falloff ratio.
    const scale = offset === 0 ? 1 : abs === 1 ? sideScale : sideScale * sideScale;
    const step = spacing + (abs - 1) * (spacing * 0.65);
    const shift = offset === 0 ? 0 : offset > 0 ? step : -step;
    const opacity = abs > 2 ? 0 : abs === 2 ? 0.35 : abs === 1 ? 0.75 : 1;
    const zIndex = 10 - abs;
    const blur = abs >= 2 ? 1 : 0;
    return {
      transform: `translate(-50%, -50%) translateX(${shift}%) scale(${scale})`,
      opacity,
      zIndex,
      filter: blur ? `blur(${blur}px)` : "none",
      transition: `transform ${speed}ms cubic-bezier(0.22, 1, 0.36, 1), opacity ${speed}ms ease, filter ${speed}ms ease`,
    };
  };

  const cssVars = {
    "--carousel-accent": accent,
    "--carousel-card-w": `${cardWidth}px`,
    "--carousel-card-h": `${cardHeight}px`,
    "--carousel-radius": `${radius}px`,
  };

  return (
    <div ref={containerRef} tabIndex={0} className="carousel" style={cssVars}>
      <div className="carousel-stage">
        {visible.map(({ slide, i, offset }) => (
          <button
            key={slide.id}
            onClick={() => offset !== 0 && goTo(i)}
            aria-label={offset === 0 ? `${slide.title}, current slide` : `Go to ${slide.title}`}
            className={`carousel-card${offset === 0 ? " carousel-card--active" : ""}`}
            style={{
              ...styleFor(offset),
              cursor: offset === 0 ? "default" : "pointer",
            }}
          >
            <img
              src={slide.image}
              alt={slide.title}
              className="carousel-card__img"
              draggable={false}
            />
            <div className="carousel-card__shade" />
            {showCaption && offset === 0 && (
              <div className="carousel-card__info">
                <span className="carousel-card__count">
                  {String(i + 1).padStart(2, "0")} / {String(count).padStart(2, "0")}
                </span>
                <h3 className="carousel-card__title">{slide.title}</h3>
                <p className="carousel-card__subtitle">{slide.subtitle}</p>
              </div>
            )}
          </button>
        ))}
      </div>

      {showArrows && (
        <>
          <button
            onClick={prev}
            aria-label="Previous slide"
            className="carousel-control carousel-control--prev"
          >
            <Chevron direction="left" />
          </button>
          <button
            onClick={next}
            aria-label="Next slide"
            className="carousel-control carousel-control--next"
          >
            <Chevron direction="right" />
          </button>
        </>
      )}

      {showDots && (
        <div className="carousel-dots">
          {slides.map((slide, i) => (
            <button
              key={slide.id}
              onClick={() => goTo(i)}
              aria-label={`Go to slide ${i + 1}`}
              aria-current={i === index}
              className="carousel-dot"
              style={{
                width: i === index ? 22 : 8,
                backgroundColor: i === index ? accent : dotColor,
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

.carousel {
  /* Defaults — the component overrides these inline from its props. */
  --carousel-accent: #ffffff;
  --carousel-card-w: 280px;
  --carousel-card-h: 400px;
  --carousel-radius: 16px;

  position: relative;
  width: 100%;
  max-width: 768px;
  margin: 0 auto;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  font-family: ui-sans-serif, system-ui, sans-serif;
}

.carousel-stage {
  position: relative;
  height: calc(var(--carousel-card-h) + 80px);
  perspective: 1200px;
}

.carousel-card {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--carousel-card-w);
  height: var(--carousel-card-h);
  padding: 0;
  border: 3px solid transparent;
  border-radius: var(--carousel-radius);
  overflow: hidden;
  background: #000;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.4);
  -webkit-tap-highlight-color: transparent;
}

.carousel-card:focus-visible {
  outline: 3px solid var(--carousel-accent);
  outline-offset: 2px;
}

.carousel-card--active {
  border-color: var(--carousel-accent);
}

.carousel-card__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.carousel-card__shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.75) 0%,
    rgba(0, 0, 0, 0.05) 45%,
    transparent 70%
  );
}

.carousel-card__info {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  text-align: left;
  color: #fff;
}

.carousel-card__count {
  color: rgba(255, 255, 255, 0.7);
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.carousel-card__title {
  margin: 4px 0 0;
  font-size: 20px;
  line-height: 1.25;
  font-weight: 600;
}

.carousel-card__subtitle {
  margin: 2px 0 0;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.8);
}

.carousel-control {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  cursor: pointer;
  backdrop-filter: blur(4px);
  transition: background-color 150ms ease;
  z-index: 20;
}

.carousel-control:hover {
  background: rgba(0, 0, 0, 0.7);
}

.carousel-control:focus-visible {
  outline: 2px solid var(--carousel-accent);
  outline-offset: 2px;
}

.carousel-control--prev {
  left: -16px;
}

.carousel-control--next {
  right: -16px;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}

.carousel-dot {
  height: 6px;
  border: none;
  border-radius: 9999px;
  padding: 0;
  cursor: pointer;
  transition: width 200ms ease;
}

@media (max-width: 640px) {
  .carousel-card {
    /* Never let a wide card setting overflow a phone screen. */
    width: min(var(--carousel-card-w), 68vw);
    height: min(var(--carousel-card-h), 96vw);
  }

  .carousel-stage {
    height: calc(min(var(--carousel-card-h), 96vw) + 60px);
  }

  .carousel-control--prev {
    left: 0;
  }

  .carousel-control--next {
    right: 0;
  }

  .carousel-card__info {
    padding: 16px;
  }

  .carousel-card__title {
    font-size: 18px;
  }

  .carousel-card__subtitle {
    font-size: 12px;
  }
}
